import React, { useEffect } from 'react';
import { envConfig } from "../utils/env.config";

function TopicImageView({ themeId, topicIdList, topics }: {
    themeId: string;
    topicIdList: string[];
    topics: string[];
}) {
    useEffect(() => {
        console.log('Received topics: ', topics);
    }, [topics]);
    return (
        <>
            {/* <h1 className="text-2xl text-center w-full">Theme {themeId}</h1> */}
            <div className={`grid gap-4 ${topicIdList.length === 1 ? 'grid-cols-1' : 'grid-cols-1 sm:grid-cols-3 md:grid-cols-3'}`}>
                {topicIdList.map((topic, index) => (
                    <div key={index} className={`text-center ${topicIdList.length === 1 ? 'col-span-1' : ''}`}>
                        <figure className="figure-container">
                            <figcaption className="font-bold capitalize">
                                {topics[parseInt(topic) - 1]}
                            </figcaption>
                            <img
                                src={`${envConfig.theme_img?.base_url || localStorage.getItem('acnt::imgBaseUrl')}/${themeId}/${topic}.jpg`}
                                alt={`Topic ${index + 1}`}
                                className="w-full h-auto object-contain"
                                style={{ maxHeight: '300px' }}
                            />
                        </figure>
                    </div>
                ))}
            </div>
        </>
    );
}

export { TopicImageView };
