import { useEffect, useRef, useCallback, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { RealtimeClient } from '@openai/realtime-api-beta';
import { ItemType } from '@openai/realtime-api-beta/dist/lib/client.js';
import { WavRecorder, WavStreamPlayer } from '../lib/wavtools/index.js';
import { instructions } from '../utils/conversation_config.js';
import { Link, useLocation } from 'react-router-dom';
import { WavRenderer } from '../utils/wav_renderer';
import LanguageSelector from '../components/language/LanguageSelector';

import { X, LogOut, Zap, ArrowUp, ArrowDown } from 'react-feather';
import { Button } from '../components/button/Button';
import { Toggle } from '../components/toggle/Toggle';
import { Map } from '../components/Map';
import { TopicImageView } from '../components/TopicImageView';
import { ConfirmModal } from '../components/modal/Modal';

import './ConsolePage.scss';
import { isJsxOpeningLikeElement } from 'typescript';

import { Theme } from '../lib/themes';
import apiService from '../lib/apiServer';

import { getInitialSystemPrompt, SysPromptOpt } from '../agent/systemMessages';
import { envConfig } from "../utils/env.config";

/**
 * Type for result from get_weather() function call
 */
interface Coordinates {
  lat: number;
  lng: number;
  location?: string;
  temperature?: {
    value: number;
    units: string;
  };
  wind_speed?: {
    value: number;
    units: string;
  };
}

/**
 * Type for all event logs
 */
interface RealtimeEvent {
  time: string;
  source: 'client' | 'server';
  count?: number;
  event: { [key: string]: any };
}

const generateRandomInt = (min: number, max: number) => {
  return Math.floor(Math.random() * (max - min + 1)) + min;
};

interface ConsolePageProps {
  onLogout: () => void;
  apiKey: string;
  theme: Theme;
}

// export function ConsolePage() {
const ConsolePage: React.FC<ConsolePageProps> = ({ onLogout, apiKey, theme }) => {
  // Check for debug mode from URL parameters
  const location = useLocation();
  const urlParams = new URLSearchParams(location.search);
  const isDebugMode = urlParams.get('debug') === 'true';

  /**
   * Instantiate:
   * - WavRecorder (speech input)
   * - WavStreamPlayer (speech output)
   * - RealtimeClient (API client)
   */
  const wavRecorderRef = useRef<WavRecorder>(
    new WavRecorder({ sampleRate: 24000 })
  );
  const wavStreamPlayerRef = useRef<WavStreamPlayer>(
    new WavStreamPlayer({ sampleRate: 24000 })
  );
  const clientRef = useRef<RealtimeClient>(
    new RealtimeClient({
            apiKey: apiKey,  // Ensure apiKey is always a string
            dangerouslyAllowAPIKeyInBrowser: true,
          }
    )
  );

  /**
   * References for
   * - Rendering audio visualization (canvas)
   * - Autoscrolling event logs
   * - Timing delta for event log displays
   */
  const clientCanvasRef = useRef<HTMLCanvasElement>(null);
  const serverCanvasRef = useRef<HTMLCanvasElement>(null);
  const eventsScrollHeightRef = useRef(0);
  const eventsScrollRef = useRef<HTMLDivElement>(null);
  const startTimeRef = useRef<string>(new Date().toISOString());

  /**
   * All of our variables for displaying application state
   * - items are all conversation items (dialog)
   * - realtimeEvents are event logs, which can be expanded
   * - memoryKv is for set_memory() function
   * - coords, marker are for get_weather() function
   */
  const [items, setItems] = useState<ItemType[]>([]);
  const [realtimeEvents, setRealtimeEvents] = useState<RealtimeEvent[]>([]);
  const [expandedEvents, setExpandedEvents] = useState<{
    [key: string]: boolean;
  }>({});
  const [isConnected, setIsConnected] = useState(false);
  const [canPushToTalk, setCanPushToTalk] = useState(true);
  const [isRecording, setIsRecording] = useState(false);
  const [memoryKv, setMemoryKv] = useState<{ [key: string]: any }>(() => {
    const storedMemoryKv = localStorage.getItem('acnt::memoryKv');
    return storedMemoryKv ? JSON.parse(storedMemoryKv) : {};
  });
  // const [coords, setCoords] = useState<Coordinates | null>({
  //   lat: 37.775593,
  //   lng: -122.418137,
  // });
  // const [marker, setMarker] = useState<Coordinates | null>(null);

  // topic IDs to display
  const [topicIdList, setTopicIdList] = useState<string[]>([]);

  const { t } = useTranslation();
  const botName = t('common.botName');

  // show conversation panel
  const [showConversation, setShowConversation] = useState(false);

  // current duration display
  const [currentDuration, setCurrentDuration] = useState('00:00');

  // Modal states for feedback and data sharing
  const [showFeedbackModal, setShowFeedbackModal] = useState(false);
  const [showDataSharingModal, setShowDataSharingModal] = useState(false);
  const [showNewConversationModal, setShowNewConversationModal] = useState(false);

  // Save memoryKv to localStorage whenever it changes
  useEffect(() => {
    localStorage.setItem('acnt::memoryKv', JSON.stringify(memoryKv));
  }, [memoryKv]);

  /**
   * Update current duration continuously when connected
   */
  useEffect(() => {
    let intervalId: NodeJS.Timeout;

    if (isConnected) {
      intervalId = setInterval(() => {
        const startTime = new Date(startTimeRef.current).getTime();
        const currentTime = new Date().getTime();
        const duration = currentTime - startTime;
        const minutes = Math.floor(duration / 60000);
        const seconds = Math.floor((duration % 60000) / 1000);
        const formattedDuration = `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
        setCurrentDuration(formattedDuration);
      }, 1000);
    }
    // When disconnected, don't reset the timer - just stop updating it

    return () => {
      if (intervalId) {
        clearInterval(intervalId);
      }
    };
  }, [isConnected]);

  /**
   * Utility for formatting the timing of logs
   */
  const formatTime = useCallback((timestamp: string) => {
    const startTime = startTimeRef.current;
    const t0 = new Date(startTime).valueOf();
    const t1 = new Date(timestamp).valueOf();
    const delta = t1 - t0;
    const hs = Math.floor(delta / 10) % 100;
    const s = Math.floor(delta / 1000) % 60;
    const m = Math.floor(delta / 60_000) % 60;
    const pad = (n: number) => {
      let s = n + '';
      while (s.length < 2) {
        s = '0' + s;
      }
      return s;
    };
    return `${pad(m)}:${pad(s)}.${pad(hs)}`;
  }, []);

  /**
   * When you click the API key
   */
  const resetAPIKey = useCallback(() => {
    const apiKey = prompt('OpenAI API Key');
    if (apiKey !== null) {
      localStorage.clear();
      localStorage.setItem('acnt::voice_api_key', apiKey);
      window.location.reload();
    }
  }, []);

  /**
   * Connect to conversation:
   * WavRecorder taks speech input, WavStreamPlayer output, client is API client
   */
  const connectConversation = useCallback(async () => {
    const client = clientRef.current;
    const wavRecorder = wavRecorderRef.current;
    const wavStreamPlayer = wavStreamPlayerRef.current;

    // Init theme
    // setThemeId(JSON.parse(localStorage.getItem('acnt::theme') ?? "")['id']);

    // Set state variables
    startTimeRef.current = new Date().toISOString();
    setIsConnected(true);
    // setRealtimeEvents([]);
    setItems(client.conversation.getItems());

    // Connect to microphone
    await wavRecorder.begin();

    // Connect to audio output
    await wavStreamPlayer.connect();

    // Connect to realtime API
    await client.connect();
    client.sendUserMessageContent([
      {
        type: `input_text`,
        text: t('common.greeting'),
        // text: `For testing purposes, I want you to list ten car brands. Number each item, e.g. "one (or whatever number you are one): the item name".`
      },
    ]);

    if (client.getTurnDetectionType() === 'server_vad') {
      await wavRecorder.record((data) => client.appendInputAudio(data.mono));
    }

    // changeTurnEndType('server_vad');
  }, []);

  /**
   * Disconnect and reset conversation state
   */
  const disconnectConversation = useCallback(async () => {
    setIsConnected(false);
    // setRealtimeEvents([]);
    // setItems([]);

    const client = clientRef.current;
    client.disconnect();

    const wavRecorder = wavRecorderRef.current;
    await wavRecorder.end();

    const wavStreamPlayer = wavStreamPlayerRef.current;
    await wavStreamPlayer.interrupt();

    // Show feedback modal after a small delay
    setTimeout(() => {
      setShowFeedbackModal(true);
    }, 500);
  }, []);

  const handleFeedbackConfirm = useCallback(() => {
    window.open("https://forms.gle/aL879bVUwJUEgfpx6", "_blank");
    setShowFeedbackModal(false);
    // Show data sharing modal after feedback modal closes
    setTimeout(() => {
      setShowDataSharingModal(true);
    }, 200);
  }, []);

  const handleFeedbackDecline = useCallback(() => {
    setShowFeedbackModal(false);
    // Show data sharing modal after feedback modal closes
    setTimeout(() => {
      setShowDataSharingModal(true);
    }, 200);
  }, []);

  const handleDataSharingConfirm = useCallback(() => {
    // Generate and download the conversation log for sharing
    const jsonlData = items.map(item => {
      let content = '';
      if (item.type === 'function_call_output') {
        content = item.formatted.output || '';
      } else if (item.formatted.tool) {
        content = `${item.formatted.tool.name}(${item.formatted.tool.arguments})` || '';
      } else {
        content = item.formatted.text || item.formatted.transcript || '';
      }

      return {
        role: item.role || item.type,
        content: content,
        timestamp: new Date().toISOString()
      };
    }).map(item => JSON.stringify(item)).join('\n');

    const blob = new Blob([jsonlData], { type: 'application/jsonl' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `a-conect_shared_log_${new Date().toISOString().replace(/:/g, '-')}.jsonl`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    setShowDataSharingModal(false);

    // Show a brief thank you message and then show new conversation modal
    setTimeout(() => {
      alert("Thank you! Your conversation log has been downloaded. Please send this file to the development team.");
      // Show new conversation modal after the alert
      setTimeout(() => {
        setShowNewConversationModal(true);
      }, 200);
    }, 100);
  }, [items]);

  const handleDataSharingDecline = useCallback(() => {
    setShowDataSharingModal(false);
    // Show new conversation modal after data sharing modal closes
    setTimeout(() => {
      setShowNewConversationModal(true);
    }, 200);
  }, []);

  const handleNewConversationConfirm = useCallback(() => {
    setShowNewConversationModal(false);
    // Refresh the page to start a new conversation
    window.location.reload();
  }, []);

  const handleNewConversationDecline = useCallback(() => {
    setShowNewConversationModal(false);
  }, []);

  const deleteConversationItem = useCallback(async (id: string) => {
    const client = clientRef.current;
    client.deleteItem(id);
  }, []);

  /**
   * In push-to-talk mode, start recording
   * .appendInputAudio() for each sample
   */
  const startRecording = async () => {
    setIsRecording(true);
    const client = clientRef.current;
    const wavRecorder = wavRecorderRef.current;
    const wavStreamPlayer = wavStreamPlayerRef.current;
    const trackSampleOffset = await wavStreamPlayer.interrupt();
    if (trackSampleOffset?.trackId) {
      const { trackId, offset } = trackSampleOffset;
      await client.cancelResponse(trackId, offset);
    }
    await wavRecorder.record((data) => client.appendInputAudio(data.mono));
  };

  /**
   * In push-to-talk mode, stop recording
   */
  const stopRecording = async () => {
    setIsRecording(false);
    const client = clientRef.current;
    const wavRecorder = wavRecorderRef.current;
    await wavRecorder.pause();
    client.createResponse();
  };

  /**
   * Switch between Manual <> VAD mode for communication
   */
  const changeTurnEndType = async (value: string) => {
    const client = clientRef.current;
    const wavRecorder = wavRecorderRef.current;
    if (value === 'none' && wavRecorder.getStatus() === 'recording') {
      await wavRecorder.pause();
    }
    client.updateSession({
      turn_detection: value === 'none' ? null : { type: 'server_vad' },
    });
    if (value === 'server_vad' && client.isConnected()) {
      await wavRecorder.record((data) => client.appendInputAudio(data.mono));
    }
    setCanPushToTalk(value === 'none');
  };

  /**
   * Auto-scroll the event logs
   */
  useEffect(() => {
    if (eventsScrollRef.current) {
      const eventsEl = eventsScrollRef.current;
      const scrollHeight = eventsEl.scrollHeight;
      // Only scroll if height has just changed
      if (scrollHeight !== eventsScrollHeightRef.current) {
        eventsEl.scrollTop = scrollHeight;
        eventsScrollHeightRef.current = scrollHeight;
      }
    }
  }, [realtimeEvents]);

  /**
   * Auto-scroll the conversation logs
   */
  useEffect(() => {
    const conversationEls = [].slice.call(
      document.body.querySelectorAll('[data-conversation-content]')
    );
    for (const el of conversationEls) {
      const conversationEl = el as HTMLDivElement;
      conversationEl.scrollTop = conversationEl.scrollHeight;
    }
  }, [items]);

  /**
   * Set up render loops for the visualization canvas
   */
  useEffect(() => {
    let isLoaded = true;

    const wavRecorder = wavRecorderRef.current;
    const clientCanvas = clientCanvasRef.current;
    let clientCtx: CanvasRenderingContext2D | null = null;

    const wavStreamPlayer = wavStreamPlayerRef.current;
    const serverCanvas = serverCanvasRef.current;
    let serverCtx: CanvasRenderingContext2D | null = null;

    const render = () => {
      if (isLoaded) {
        if (clientCanvas) {
          if (!clientCanvas.width || !clientCanvas.height) {
            clientCanvas.width = clientCanvas.offsetWidth;
            clientCanvas.height = clientCanvas.offsetHeight;
          }
          clientCtx = clientCtx || clientCanvas.getContext('2d');
          if (clientCtx) {
            clientCtx.clearRect(0, 0, clientCanvas.width, clientCanvas.height);
            const result = wavRecorder.recording
              ? wavRecorder.getFrequencies('voice')
              : { values: new Float32Array([0]) };
            WavRenderer.drawBars(
              clientCanvas,
              clientCtx,
              result.values,
              '#0099ff',
              10,
              0,
              8
            );
          }
        }
        if (serverCanvas) {
          if (!serverCanvas.width || !serverCanvas.height) {
            serverCanvas.width = serverCanvas.offsetWidth;
            serverCanvas.height = serverCanvas.offsetHeight;
          }
          serverCtx = serverCtx || serverCanvas.getContext('2d');
          if (serverCtx) {
            serverCtx.clearRect(0, 0, serverCanvas.width, serverCanvas.height);
            const result = wavStreamPlayer.analyser
              ? wavStreamPlayer.getFrequencies('voice')
              : { values: new Float32Array([0]) };
            WavRenderer.drawBars(
              serverCanvas,
              serverCtx,
              result.values,
              '#009900',
              10,
              0,
              8
            );
          }
        }
        window.requestAnimationFrame(render);
      }
    };
    render();

    return () => {
      isLoaded = false;
    };
  }, []);

  /**
   * Core RealtimeClient and audio capture setup
   * Set all of our instructions, tools, events and more
   */
  useEffect(() => {
    // Get refs
    const wavStreamPlayer = wavStreamPlayerRef.current;
    const client = clientRef.current;

    // Set instructions
    client.updateSession({ instructions: getInitialSystemPrompt(SysPromptOpt.DEFAULT, JSON.stringify(memoryKv), botName) });
    client.updateSession({ voice: 'alloy' });
    // Set transcription, otherwise we don't get user transcriptions back
    client.updateSession({ input_audio_transcription: { model: 'whisper-1' } });

    // set initial turn change type
    // client.updateSession({turn_detection: { type: 'server_vad' }});
    client.updateSession({ turn_detection: { type: 'server_vad', silence_duration_ms: 500 } });
    setCanPushToTalk(false);

    // Add tools
    client.addTool(
      {
        name: 'set_memory',
        description: 'Saves important data about the user into memory. This should be called every as frequently as possible.',
        parameters: {
          type: 'object',
          properties: {
            key: {
              type: 'string',
              description:
                'The key of the memory value. Always use lowercase and underscores, no other characters. The key should be easy to recognize. For example, interest, user_name, family_members, etc.',
            },
            value: {
              type: 'string',
              description: 'Value can be anything represented as a string',
            },
          },
          required: ['key', 'value'],
        },
      },
      async ({ key, value }: { [key: string]: any }) => {
        setMemoryKv((memoryKv) => {
          const newKv = { ...memoryKv };
          newKv[key] = value;
          return newKv;
        });
        console.log(`updated memory: ${key} == ${value}`);
        return { ok: true };
      }
    );
    client.addTool(
      {
        name: 'display_topic_images',
        description: 'Display all three topic images on the screen',
        parameters: {
        },
      },
      async () => {
        console.log(`display image theme_id: ${theme.id}`);
        setTopicIdList(['1', '2', '3'])
        // setTopics(JSON.parse(localStorage.getItem('theme') ?? "")['topics']);
        return { ok: true };
      }
    );
    client.addTool(
      {
        name: 'set_topic',
        description: 'Specify a topic to talk',
        parameters: {
          type: 'object',
          properties: {
            id: {
              type: 'string',
              enum: ['1', '2', '3'],
              description: 'topic ID',
            },
          },
          required: ['id'],
        },
      },
      async ({ id }: { [key: string]: any }) => {
        setTopicIdList([id]);
        return { ok: true };
      }
    );
    client.addTool(
      {
        name: 'summarize_conversation',
        description: 'Summarize the whole conversation',
        parameters: {
          type: 'object',
          properties: {
            summary: {
              type: 'string',
              description: 'A brief summary of the conversation',
            },
          },
          required: ['summary'],
        },
      },
      async ({ summary }: { [key: string]: any }) => {
        setMemoryKv((memoryKv) => {
          const newKv = { ...memoryKv };
          newKv["last_conversation_summary"] = summary;
          return newKv;
        });
        console.log("update converssation summary", summary);
        return { ok: true };
      }
    );
    client.addTool(
      {
      name: 'get_duration',
      description: 'Summarize the whole conversation and return its duration',
      parameters: {
        type: 'object',
        properties: {},
        required: [],
      },
      },
      async () => {
      const startTime = new Date(startTimeRef.current).getTime();
      const endTime = new Date().getTime();
      const duration = endTime - startTime;
      const minutes = Math.floor(duration / 60000);
      const seconds = Math.floor((duration % 60000) / 1000);
      const formattedDuration = `${minutes} minutes ${seconds} seconds`;
      console.log("conversation duration", formattedDuration);

      return { ok: true, duration: formattedDuration };
      }
    );

    client.on('error', (event: any) => console.error(event));
    client.on('conversation.interrupted', async () => {
      const trackSampleOffset = await wavStreamPlayer.interrupt();
      if (trackSampleOffset?.trackId) {
        const { trackId, offset } = trackSampleOffset;
        await client.cancelResponse(trackId, offset);
      }
    });
    client.on('conversation.updated', async ({ item, delta }: any) => {
      const items = client.conversation.getItems();
      if (delta?.audio) {
        wavStreamPlayer.add16BitPCM(delta.audio, item.id);
      }
      if (item.status === 'completed' && item.formatted.audio?.length) {
        const wavFile = await WavRecorder.decode(
          item.formatted.audio,
          24000,
          24000
        );
        item.formatted.file = wavFile;
      }
      setItems(items);
    });

    setItems(client.conversation.getItems());

    return () => {
      // cleanup; resets to defaults
      client.reset();
    };
  }, []);

  /**
   * Render the application
   */
  return (
    <div data-component="ConsolePage">
      <div className="content-top">
        <div className="content-title">
          <img src="/openai-logomark.svg" />
          <span>A-CONECT (v2025.09.01)</span>
        </div>
        <div className="content-api-key">
          <a href="project" className="block mt-4 lg:inline-block lg:mt-0 text-black hover:bg-black hover:text-white px-2 py-1 rounded mr-4">
            {t('common.research')}
          </a>
        </div>
        <div className="content-api-key">
          <a href="https://forms.gle/aL879bVUwJUEgfpx6" className="block mt-4 lg:inline-block lg:mt-0 text-black hover:bg-black hover:text-white px-2 py-1 rounded mr-4">
            {t('common.feedback')}
          </a>
        </div>
        <div className="content-api-key">
            <Link to="/privacy" className="block mt-4 lg:inline-block lg:mt-0 text-black hover:bg-black hover:text-white px-2 py-1 rounded mr-4">
            {t('common.privacy')}
            </Link>
        </div>
        <div className="content-api-key">
            <LanguageSelector />
        </div>
        <div className="content-api-key">
            <Button
              icon={LogOut}
              iconPosition="end"
              buttonStyle="flush"
              label={t('common.logout') || 'Log Out'}
              onClick={() => onLogout()}
            />
        </div>
      </div>
      <div className="content-main">
        <div className="content-logs">
          <div className="content-block events">
          <div
            className="flex h-screen flex-col"
          >
            <div className="topic-image-container border rounded-lg p-4 flex flex-col gap-2 w-200 m-3 h-auto" style={{ maxWidth: '100%', height: 'auto' }}>
              <TopicImageView
                themeId={theme.id}
                topicIdList={topicIdList}
                topics={theme.topics}
              />

            </div>
          </div>

            <div className="content-block events">
              <div className="visualization">
                <div className="visualization-entry client">
                  <canvas ref={clientCanvasRef} />
                </div>
                <div className="visualization-entry server">
                  <canvas ref={serverCanvasRef} />
                </div>
              </div>
            </div>
          </div>
            <div className="content-block-title" onClick={() => setShowConversation(!showConversation)} style={{cursor: 'pointer', display: isDebugMode ? 'block' : 'none'}}>
              conversation log {showConversation ? '▼' : '▶'}
            </div>
            {showConversation && isDebugMode && (
              <div className="content-block conversation">
                <div className="content-block-body" data-conversation-content>
                  {!items.length && `awaiting connection...`}
                  {items.map((conversationItem, i) => {
                    return (
                      <div className="conversation-item" key={conversationItem.id}>
                        <div className={`speaker ${conversationItem.role || ''}`}>
                          <div>
                            {(
                              conversationItem.role || conversationItem.type
                            ).replaceAll('_', ' ')}
                          </div>
                          <div
                            className="close"
                            onClick={() =>
                              deleteConversationItem(conversationItem.id)
                            }
                          >
                            <X />
                          </div>
                        </div>
                        <div className={`speaker-content`}>
                          {/* tool response */}
                          {conversationItem.type === 'function_call_output' && (
                            <div>{conversationItem.formatted.output || ''}</div>
                          )}
                          {/* tool call */}
                          {!!conversationItem.formatted.tool && (
                            <div>
                              {conversationItem.formatted.tool.name}(
                              {conversationItem.formatted.tool.arguments})
                            </div>
                          )}
                          {!conversationItem.formatted.tool &&
                            conversationItem.role === 'user' && (
                              <div>
                                {conversationItem.formatted.transcript ||
                                  (conversationItem.formatted.audio?.length
                                    ? '(awaiting transcript)'
                                    : conversationItem.formatted.text ||
                                      '(item sent)')}
                              </div>
                            )}
                          {!conversationItem.formatted.tool &&
                            conversationItem.role === 'assistant' && (
                              <div>
                                {conversationItem.formatted.transcript ||
                                  conversationItem.formatted.text ||
                                  '(truncated)'}
                              </div>
                            )}
                          {/* {conversationItem.formatted.file && (
                            <audio
                              src={conversationItem.formatted.file.url}
                              controls
                            />
                          )} */}
                        </div>
                      </div>
                    );
                  })}
                </div>

                <div className="content-block kv">
                  <div className="content-block-title">{botName}'s memory</div>
                  <div className="content-block-body content-kv">
                    {JSON.stringify(memoryKv, null, 2)}
                  </div>
                </div>
              </div>
            )}
          <div className="content-actions">
            <Button
              label={t('common.saveConversation') || 'Save Conv'}
              buttonStyle="regular"
              onClick={() => {
                const jsonlData = items.map(item => {
                    let content = '';
                    if (item.type === 'function_call_output') {
                        content = item.formatted.output || '';
                    } else if (item.formatted.tool) {
                        content = `${item.formatted.tool.name}(${item.formatted.tool.arguments})` || '';
                    } else {
                        content = item.formatted.text || item.formatted.transcript || '';
                    }

                    return {
                        // id: item.id,
                        role: item.role || item.type,
                        content: content,
                        timestamp: new Date().toISOString()
                    };
                }).map(item => JSON.stringify(item)).join('\n');
                const blob = new Blob([jsonlData], { type: 'application/jsonl' });
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = `a-conect_log_${new Date().toISOString().replace(/:/g, '-')}.jsonl`;
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
                URL.revokeObjectURL(url);
              }}
            />
            {isDebugMode && (
              <Toggle
                defaultValue={true}
                labels={['manual', 'vad']}
                values={['none', 'server_vad']}
                onChange={(_, value) => changeTurnEndType(value)}
              />
            )}
            <div className="spacer" />
            {isConnected && canPushToTalk && (
              <Button
                label={isRecording ? (t('common.releaseToSend') || 'release to send') : (t('common.pushToTalk') || 'push to talk')}
                buttonStyle={isRecording ? 'alert' : 'regular'}
                disabled={!isConnected || !canPushToTalk}
                onMouseDown={startRecording}
                onMouseUp={stopRecording}
              />
            )}
            <div className="spacer" />
            {/* <Button
              label={isConnected ? 'disconnect' : 'connect'}
              iconPosition={isConnected ? 'end' : 'start'}
              icon={isConnected ? X : Zap}
              buttonStyle={isConnected ? 'regular' : 'action'}
              onClick={
                isConnected ? disconnectConversation : connectConversation
              }
            /> */}
          </div>
        </div>
        <div className="content-right">
          <div className="content-block map">
            <div className="content-block-title">{botName}
              {/* Select voice type. On hold */}
              {/* <select
                onChange={(e) => {
                  const selectedCharacter = e.target.value;
                  // Update the botName or any other state related to the character
                  console.log(`Selected voice: ${selectedCharacter}`);
                  // Update the voice in the client session
                  const client = clientRef.current;
                  const voice = selectedCharacter.toLowerCase() as 'alloy' | 'ash' | 'ballad' | 'coral' | 'echo' | 'sage' | 'shimmer' | 'verse';
                  client.updateSession({ voice });
                }}
              >
                <option value="Alloy">Alloy</option>
                <option value="Ash">Ash</option>
                <option value="Ballad">Ballad</option>
                <option value="Coral">Coral</option>
                <option value="Echo">Echo</option>
                <option value="Sage">Sage</option>
                <option value="Shimmer">Shimmer</option>
                <option value="Verse">Verse</option>
              </select> */}
            </div>
            <div className="content-block-title bottom">
              <Button
                label={isConnected ? (t('common.end') || 'end') : (t('common.start') || 'start')}
                iconPosition={isConnected ? 'end' : 'start'}
                icon={isConnected ? X : Zap}
                buttonStyle={isConnected ? 'regular' : 'action'}
                onClick={
                  isConnected ? disconnectConversation : connectConversation
                }
              />
            </div>
            <div className="content-block-body full" style={{ display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', gap: '10px' }}>
              <img src="/avatar.png" alt="Avatar" className="avatar" style={{ borderRadius: '50%' }} />
              <div style={{ fontSize: '20px', fontWeight: 'bold', color: isConnected ? '#009900' : '#666' }}>
                {currentDuration}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Feedback Modal */}
      <ConfirmModal
        isOpen={showFeedbackModal}
        onClose={handleFeedbackDecline}
        onConfirm={handleFeedbackConfirm}
        title="Feedback Request"
        message="Thank you for using A-CONECT! Would you like to provide feedback to help us improve? This will open a survey form in a new tab."
        confirmText="Yes, provide feedback"
        cancelText="Skip"
      />

      {/* Data Sharing Modal */}
      {/* <ConfirmModal
        isOpen={showDataSharingModal}
        onClose={handleDataSharingDecline}
        onConfirm={handleDataSharingConfirm}
        title="Share Conversation"
        message="Would you like to share your conversation with the development team? This helps us improve the system. Your data will be used for research purposes only."
        confirmText="Yes, share conversation"
        cancelText="No, thanks"
      /> */}

      {/* New Conversation Modal */}
      <ConfirmModal
        isOpen={showNewConversationModal}
        onClose={handleNewConversationDecline}
        onConfirm={handleNewConversationConfirm}
        title="Start New Conversation"
        message="Would you like to refresh the page to start a new conversation? This will clear your current session and begin fresh."
        confirmText="Yes, start new conversation"
        cancelText="No, stay here"
      />
    </div>
  );
}

export default ConsolePage;
